  cursor: number | null;
  has_more: boolean;
}> {
  const base: Record<string, string | number | boolean> = {
    business_id: businessId,
    status: "PUBLIC",
    cursor: Math.max(0, cursor),
    max_count: Math.min(Math.max(1, maxCount), BUSINESS_COMMENT_MAX_COUNT),
