import { getTikTokContentAccessToken } from "./tiktokContentOrgResolver.ts";

type AccountRow = {
  id: string;
  open_id: string;
  label: string;
  display_name: string | null;
  avatar_url?: string | null;
  is_active: boolean;
};

/** Labels generated before we fetched TikTok profile (open_id fragment). */
export function isPlaceholderTikTokAccountLabel(
  label: string | null | undefined,
  openId: string,
): boolean {
  const trimmed = label?.trim() ?? "";
  if (!trimmed) return true;
  if (trimmed === openId) return true;
  if (/^TikTok\s+-?[\w]{4,16}$/i.test(trimmed)) return true;
  const idPrefix = openId.replace(/^-/, "").slice(0, 8);
  if (idPrefix && trimmed.toLowerCase().includes(idPrefix.toLowerCase())) return true;
  return false;
}

export function pickTikTokAccountLabel(account: {
  label?: string | null;
  display_name?: string | null;
  open_id: string;
}): string {
  for (const raw of [account.display_name, account.label]) {
    const name = raw?.trim() ?? "";
    if (name && !isPlaceholderTikTokAccountLabel(name, account.open_id)) return name;
  }
  return account.display_name?.trim() || account.label?.trim() || "TikTok";
}

export async function fetchTikTokAccountProfileFromApi(
  accessToken: string,
): Promise<{ displayName: string | null; avatarUrl: string | null } | null> {
  try {
    const user = await fetchTikTokUserInfo(accessToken);
    return {
      displayName: user.display_name?.trim() || null,
      avatarUrl: user.avatar_url?.trim() || null,
    };
  } catch (e) {
    console.warn("fetchTikTokAccountProfileFromApi:", e instanceof Error ? e.message : e);
    return null;
  }
}

function isTikTokHostedAvatarUrl(url: string | null | undefined): boolean {
  const u = url?.trim().toLowerCase() ?? "";
  if (!u) return false;
  return (
    u.includes("tiktokcdn")
    || u.includes("tiktokv.com")
    || u.includes("muscdn.com")
    || u.includes("byteoversea.com")
  );
}

export async function syncTikTokContentAccountProfiles(
  admin: SupabaseClient,
  organizationId: string,
  accounts: AccountRow[],
): Promise<number> {
  let updated = 0;
  const now = new Date().toISOString();

  for (const acc of accounts) {
    if (!acc.is_active) continue;
    const needsLabelSync = isPlaceholderTikTokAccountLabel(acc.label, acc.open_id)
      || isPlaceholderTikTokAccountLabel(acc.display_name, acc.open_id);
    const needsAvatarSync = !acc.avatar_url?.trim() || isTikTokHostedAvatarUrl(acc.avatar_url);
    if (!needsLabelSync && !needsAvatarSync) continue;

    const tokenResult = await getTikTokContentAccessToken(admin, organizationId, acc.open_id);
    if (!tokenResult) continue;

    const profile = await fetchTikTokAccountProfileFromApi(tokenResult.accessToken);
    if (!profile) continue;
    if (!needsLabelSync && !profile.avatarUrl) continue;

    const updatePayload: Record<string, string | null> = { updated_at: now };
    if (needsLabelSync && profile.displayName) {
      updatePayload.label = profile.displayName;
      updatePayload.display_name = profile.displayName;
    }
    if (needsAvatarSync && profile.avatarUrl) {
      updatePayload.avatar_url = profile.avatarUrl;
    }
    if (Object.keys(updatePayload).length <= 1) continue;

    const { error } = await admin
      .from("organization_tiktok_content_accounts")
      .update(updatePayload)
      .eq("id", acc.id)
      .eq("organization_id", organizationId);

    if (!error) updated += 1;
  }

  return updated;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptTikTokContentToken,
  encryptTikTokContentToken,
} from "./tiktokContentConfigCrypto.ts";
import {
  mergeTikTokContentOAuthScopes,
  readPlatformTikTokContentOAuth,
  readPlatformTikTokContentPublishOAuth,
  TIKTOK_CONTENT_OAUTH_SCOPES,
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
  type TikTokContentOAuthTokenKind,
} from "./tiktokContentAuth.ts";
import {
  refreshTikTokBusinessOrganicAccessToken,
  refreshTikTokContentAccessToken,
} from "./tiktokContentApi.ts";

export type TikTokContentAccountRow = {
  id: string;
  organization_id: string;
  open_id: string;
  label: string;
  display_name: string | null;
  avatar_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
  oauth_scopes: string | null;
  oauth_token_kind: string | null;
  publish_access_token_enc?: string | null;
  publish_refresh_token_enc?: string | null;
  publish_access_token_expires_at?: string | null;
  publish_oauth_scopes?: string | null;
};

function normalizeTokenKind(raw: string | null | undefined): TikTokContentOAuthTokenKind {
  return raw === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    ? TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    : TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit;
}

export async function getTikTokContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<{ accessToken: string; tokenKind: TikTokContentOAuthTokenKind } | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at, oauth_scopes, oauth_token_kind")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch (e) {
      console.error("getTikTokContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptTikTokContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getTikTokContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformTikTokContentOAuth();
  const refreshed = oauth
    ? tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
      ? await refreshTikTokBusinessOrganicAccessToken(
        oauth.clientKey,
        oauth.clientSecret,
        refreshToken,
      )
      : await refreshTikTokContentAccessToken(oauth.clientKey, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch {
      return null;
    }
  }

  try {
    const now = new Date().toISOString();
    const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
    const refreshEnc = refreshed.refresh_token
      ? await encryptTikTokContentToken(refreshed.refresh_token)
      : String(tokenRow.refresh_token_enc);
    const accessExpires = refreshed.expires_in
      ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
      : tokenRow.access_token_expires_at;

    const resolvedScopes = mergeTikTokContentOAuthScopes(
      tokenRow.oauth_scopes,
      refreshed.scope,
      TIKTOK_CONTENT_OAUTH_SCOPES,
    );

    await admin.from("organization_tiktok_content_connection_tokens").update({
      access_token_enc: accessEnc,
      refresh_token_enc: refreshEnc,
      access_token_expires_at: accessExpires,
      oauth_scopes: resolvedScopes,
      updated_at: now,
    }).eq("organization_id", organizationId).eq("open_id", openId);
  } catch (e) {
    console.error("getTikTokContentAccessToken persist refresh:", e);
  }

  return { accessToken: refreshed.access_token, tokenKind };
}

export async function getTikTokPublishAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select(
      "access_token_enc, refresh_token_enc, access_token_expires_at, oauth_token_kind, publish_access_token_enc, publish_refresh_token_enc, publish_access_token_expires_at, publish_oauth_scopes, oauth_scopes",
    )
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const hasPublishVault = Boolean(tokenRow.publish_access_token_enc && tokenRow.publish_refresh_token_enc);

  const publishExpiresAtMs = tokenRow.publish_access_token_expires_at
    ? new Date(String(tokenRow.publish_access_token_expires_at)).getTime()
    : null;
  const publishNeedsRefresh = hasPublishVault &&
    publishExpiresAtMs != null &&
    Number.isFinite(publishExpiresAtMs) &&
    publishExpiresAtMs < Date.now() + 60_000;

  if (hasPublishVault && !publishNeedsRefresh) {
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch (e) {
      console.error("getTikTokPublishAccessToken decrypt publish:", e);
    }
  }

  if (hasPublishVault && publishNeedsRefresh) {
    const publishOAuth = readPlatformTikTokContentPublishOAuth() ?? readPlatformTikTokContentOAuth();
    if (publishOAuth) {
      try {
        const refreshToken = await decryptTikTokContentToken(
          String(tokenRow.publish_refresh_token_enc),
        );
        const refreshed = await refreshTikTokContentAccessToken(
          publishOAuth.clientKey,
          publishOAuth.clientSecret,
          refreshToken,
        );
        if (refreshed?.access_token) {
          const now = new Date().toISOString();
          const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
          const refreshEnc = refreshed.refresh_token
            ? await encryptTikTokContentToken(refreshed.refresh_token)
            : String(tokenRow.publish_refresh_token_enc);
          const accessExpires = refreshed.expires_in
            ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
            : tokenRow.publish_access_token_expires_at;
          const publishScopes = mergeTikTokContentOAuthScopes(
            tokenRow.publish_oauth_scopes,
            refreshed.scope,
            TIKTOK_CONTENT_OAUTH_SCOPES,
          );
          await admin.from("organization_tiktok_content_connection_tokens").update({
            publish_access_token_enc: accessEnc,
            publish_refresh_token_enc: refreshEnc,
            publish_access_token_expires_at: accessExpires,
            publish_oauth_scopes: publishScopes,
            updated_at: now,
          }).eq("organization_id", organizationId).eq("open_id", openId);
          return refreshed.access_token;
        }
      } catch (e) {
        console.error("getTikTokPublishAccessToken refresh publish:", e);
      }
    }
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch {
      /* fall through */
    }
  }

  if (tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit) {
    const primary = await getTikTokContentAccessToken(admin, organizationId, openId);
    return primary?.accessToken ?? null;
  }

  return null;
}

export async function resolveOrgTikTokContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  openIdParam?: string | null,
): Promise<{
  accessToken: string;
  account: TikTokContentAccountRow;
  tokenKind: TikTokContentOAuthTokenKind;
} | null> {
  let account: TikTokContentAccountRow | null = null;

  if (openIdParam) {
    const { data: row } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("open_id", openIdParam.trim())
      .maybeSingle();
    if (row) account = row as TikTokContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .maybeSingle();
    account = (defaultRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account?.open_id) return null;

  const tokenResult = await getTikTokContentAccessToken(admin, organizationId, account.open_id);
  if (!tokenResult) return null;

  return {
    accessToken: tokenResult.accessToken,
    account,
    tokenKind: tokenResult.tokenKind,
  };
}

/**
 * AES-256-GCM for TikTok Content OAuth tokens.
 * Reuses TIKTOK_ADS_CONFIG_ENCRYPTION_KEY (or TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptTikTokContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptTikTokContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export type InboxPostStateRow = {
  video_id: string;
  last_known_comment_count: number;
  is_highlighted: boolean;
  pinned_at: string | null;
};

export type InboxInboundCommentRow = {
  video_id: string;
  comment_id: string;
  detected_at: string;
};

export type ManageCommentsInboxState = {
  posts: InboxPostStateRow[];
  inbound_comments: InboxInboundCommentRow[];
  engaged_comment_ids: string[];
};

type PostBaselineInput = {
  video_id: string;
  comment_count: number;
};

export async function getManageCommentsInboxState(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<ManageCommentsInboxState> {
  const [postsRes, inboundRes, engagedRes] = await Promise.all([
    admin
      .from("tiktok_manage_comments_post_inbox_state")
      .select("video_id, last_known_comment_count, is_highlighted, pinned_at, thread_comments_seeded")
      .eq("organization_id", organizationId)
      .eq("open_id", openId),
    admin
      .from("tiktok_manage_comments_inbound_comments")
      .select("video_id, comment_id, detected_at")
      .eq("organization_id", organizationId)
      .eq("open_id", openId),
    admin
      .from("tiktok_manage_comments_comment_engagements")
      .select("comment_id")
      .eq("organization_id", organizationId)
      .eq("open_id", openId),
  ]);

  if (postsRes.error) throw new Error(postsRes.error.message);
  if (inboundRes.error) throw new Error(inboundRes.error.message);
  if (engagedRes.error) throw new Error(engagedRes.error.message);

  return {
    posts: (postsRes.data ?? []).map((row) => ({
      video_id: String(row.video_id),
      last_known_comment_count: Number(row.last_known_comment_count ?? 0),
      is_highlighted: Boolean(row.is_highlighted),
      pinned_at: row.pinned_at ?? null,
    })),
    inbound_comments: (inboundRes.data ?? []).map((row) => ({
      video_id: String(row.video_id),
      comment_id: String(row.comment_id),
      detected_at: String(row.detected_at),
    })),
    engaged_comment_ids: (engagedRes.data ?? []).map((row) => String(row.comment_id)),
  };
}

async function hasUnengagedInboundComments(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoId: string,
): Promise<boolean> {
  const [{ data: inbound }, { data: engaged }] = await Promise.all([
    admin
      .from("tiktok_manage_comments_inbound_comments")
      .select("comment_id")
      .eq("organization_id", organizationId)
      .eq("open_id", openId)
      .eq("video_id", videoId),
    admin
      .from("tiktok_manage_comments_comment_engagements")
      .select("comment_id")
      .eq("organization_id", organizationId)
      .eq("open_id", openId)
      .eq("video_id", videoId),
  ]);

  const engagedSet = new Set((engaged ?? []).map((r) => String(r.comment_id)));
  return (inbound ?? []).some((r) => !engagedSet.has(String(r.comment_id)));
}

async function clearInboundForVideos(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoIds: string[],
): Promise<void> {
  if (videoIds.length === 0) return;
  const { error } = await admin
    .from("tiktok_manage_comments_inbound_comments")
    .delete()
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .in("video_id", videoIds);
  if (error) throw new Error(error.message);
}

async function reconcilePostHighlight(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoId: string,
  lastKnownCommentCount: number,
): Promise<void> {
  const hasUnengaged = await hasUnengagedInboundComments(
    admin,
    organizationId,
    openId,
    videoId,
  );
  const shouldHighlight = hasUnengaged && lastKnownCommentCount > 0;
  const now = new Date().toISOString();

  const { data: postRow } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .select("pinned_at")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", videoId)
    .maybeSingle();

  await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .upsert({
      organization_id: organizationId,
      open_id: openId,
      video_id: videoId,
      last_known_comment_count: lastKnownCommentCount,
      is_highlighted: shouldHighlight,
      pinned_at: shouldHighlight ? (postRow?.pinned_at ?? now) : null,
      updated_at: now,
    }, { onConflict: "organization_id,open_id,video_id" });
}

export async function dismissManageCommentsPostHighlight(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoId: string,
): Promise<ManageCommentsInboxState> {
  const trimmedVideoId = videoId.trim();
  if (!trimmedVideoId) throw new Error("Missing video_id");

  const now = new Date().toISOString();
  const { data: postRow } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .select("last_known_comment_count")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", trimmedVideoId)
    .maybeSingle();

  await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .upsert({
      organization_id: organizationId,
      open_id: openId,
      video_id: trimmedVideoId,
      last_known_comment_count: Number(postRow?.last_known_comment_count ?? 0),
      is_highlighted: false,
      pinned_at: null,
      updated_at: now,
    }, { onConflict: "organization_id,open_id,video_id" });

  return getManageCommentsInboxState(admin, organizationId, openId);
}

export async function syncManageCommentsPostBaselines(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  posts: PostBaselineInput[],
): Promise<ManageCommentsInboxState> {
  if (posts.length === 0) {
    return getManageCommentsInboxState(admin, organizationId, openId);
  }

  const videoIds = posts.map((p) => p.video_id);
  const { data: existingRows, error: fetchErr } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .select("video_id, last_known_comment_count, is_highlighted, pinned_at, thread_comments_seeded")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .in("video_id", videoIds);

  if (fetchErr) throw new Error(fetchErr.message);

  const existingByVideo = new Map(
    (existingRows ?? []).map((row) => [String(row.video_id), row]),
  );

  const now = new Date().toISOString();
  const upserts = posts.map((post) => {
    const prev = existingByVideo.get(post.video_id);
    const prevCount = prev != null ? Number(prev.last_known_comment_count ?? 0) : null;
    const countIncreased = prevCount != null && post.comment_count > prevCount;
    const isNew = prev == null;

    let isHighlighted = Boolean(prev?.is_highlighted);
    let pinnedAt: string | null = prev?.pinned_at ?? null;

    if (post.comment_count === 0) {
      isHighlighted = false;
      pinnedAt = null;
    } else if (countIncreased) {
      isHighlighted = true;
      pinnedAt = now;
    } else if (isNew && post.comment_count > 0) {
      // First time we see a video with comments — establish baseline only, no highlight.
      isHighlighted = false;
    }

    return {
      organization_id: organizationId,
      open_id: openId,
      video_id: post.video_id,
      last_known_comment_count: post.comment_count,
      is_highlighted: isHighlighted,
      thread_comments_seeded: Boolean(prev?.thread_comments_seeded),
      pinned_at: pinnedAt,
      updated_at: now,
    };
  });

  const { error: upsertErr } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .upsert(upserts, { onConflict: "organization_id,open_id,video_id" });

  if (upsertErr) throw new Error(upsertErr.message);

  const zeroCommentVideoIds = posts
    .filter((post) => post.comment_count === 0)
    .map((post) => post.video_id);
  await clearInboundForVideos(admin, organizationId, openId, zeroCommentVideoIds);

  return getManageCommentsInboxState(admin, organizationId, openId);
}

export async function syncManageCommentsInboundComments(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoId: string,
  commentIds: string[],
): Promise<ManageCommentsInboxState> {
  const uniqueIds = [...new Set(commentIds.map((id) => id.trim()).filter(Boolean))];
  const now = new Date().toISOString();
  const { data: postRow, error: postErr } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .select("thread_comments_seeded, is_highlighted, last_known_comment_count, pinned_at")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", videoId)
    .maybeSingle();

  if (postErr) throw new Error(postErr.message);

  const lastKnownCount = Number(postRow?.last_known_comment_count ?? 0);

  if (uniqueIds.length === 0) {
    await clearInboundForVideos(admin, organizationId, openId, [videoId]);
    await admin
      .from("tiktok_manage_comments_post_inbox_state")
      .upsert({
        organization_id: organizationId,
        open_id: openId,
        video_id: videoId,
        last_known_comment_count: lastKnownCount,
        is_highlighted: false,
        thread_comments_seeded: true,
        pinned_at: null,
        updated_at: now,
      }, { onConflict: "organization_id,open_id,video_id" });
    return getManageCommentsInboxState(admin, organizationId, openId);
  }

  const threadSeeded = Boolean(postRow?.thread_comments_seeded);

  const { data: existingInbound, error: inboundErr } = await admin
    .from("tiktok_manage_comments_inbound_comments")
    .select("comment_id")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", videoId);

  if (inboundErr) throw new Error(inboundErr.message);

  const currentIdSet = new Set(uniqueIds);
  const staleInboundIds = (existingInbound ?? [])
    .map((r) => String(r.comment_id))
    .filter((id) => !currentIdSet.has(id));
  if (staleInboundIds.length > 0) {
    const { error: staleErr } = await admin
      .from("tiktok_manage_comments_inbound_comments")
      .delete()
      .eq("organization_id", organizationId)
      .eq("open_id", openId)
      .eq("video_id", videoId)
      .in("comment_id", staleInboundIds);
    if (staleErr) throw new Error(staleErr.message);
  }

  const existingSet = new Set(
    (existingInbound ?? [])
      .map((r) => String(r.comment_id))
      .filter((id) => currentIdSet.has(id)),
  );

  const { data: engagedRows, error: engagedErr } = await admin
    .from("tiktok_manage_comments_comment_engagements")
    .select("comment_id")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", videoId);

  if (engagedErr) throw new Error(engagedErr.message);

  const engagedSet = new Set((engagedRows ?? []).map((r) => String(r.comment_id)));

  if (!threadSeeded) {
    const baselineIds = uniqueIds.filter((id) => !engagedSet.has(id));
    if (baselineIds.length > 0) {
      const { error: insertErr } = await admin
        .from("tiktok_manage_comments_inbound_comments")
        .upsert(
          baselineIds.map((comment_id) => ({
            organization_id: organizationId,
            open_id: openId,
            video_id: videoId,
            comment_id,
            detected_at: now,
          })),
          { onConflict: "organization_id,open_id,video_id,comment_id", ignoreDuplicates: true },
        );
      if (insertErr) throw new Error(insertErr.message);
    }

    await admin
      .from("tiktok_manage_comments_post_inbox_state")
      .upsert({
        organization_id: organizationId,
        open_id: openId,
        video_id: videoId,
        last_known_comment_count: lastKnownCount,
        is_highlighted: false,
        thread_comments_seeded: true,
        pinned_at: null,
        updated_at: now,
      }, { onConflict: "organization_id,open_id,video_id" });

    return getManageCommentsInboxState(admin, organizationId, openId);
  }

  const freshIds = uniqueIds.filter((id) => !existingSet.has(id) && !engagedSet.has(id));
  if (freshIds.length > 0) {
    const { error: insertErr } = await admin
      .from("tiktok_manage_comments_inbound_comments")
      .upsert(
        freshIds.map((comment_id) => ({
          organization_id: organizationId,
          open_id: openId,
          video_id: videoId,
          comment_id,
          detected_at: now,
        })),
        { onConflict: "organization_id,open_id,video_id,comment_id", ignoreDuplicates: true },
      );
    if (insertErr) throw new Error(insertErr.message);

    await admin
      .from("tiktok_manage_comments_post_inbox_state")
      .upsert({
        organization_id: organizationId,
        open_id: openId,
        video_id: videoId,
        last_known_comment_count: lastKnownCount,
        is_highlighted: true,
        thread_comments_seeded: true,
        pinned_at: now,
        updated_at: now,
      }, { onConflict: "organization_id,open_id,video_id" });
  } else {
    await reconcilePostHighlight(admin, organizationId, openId, videoId, lastKnownCount);
  }

  return getManageCommentsInboxState(admin, organizationId, openId);
}

export type ManageCommentsEngagementType = "like" | "reply" | "delete" | "hide";

export async function markManageCommentsCommentEngaged(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  videoId: string,
  commentId: string,
  engagementType: ManageCommentsEngagementType,
  engagedBy: string | null,
): Promise<ManageCommentsInboxState> {
  const trimmedCommentId = commentId.trim();
  const trimmedVideoId = videoId.trim();
  if (!trimmedCommentId || !trimmedVideoId) {
    throw new Error("Missing video_id or comment_id");
  }

  const now = new Date().toISOString();

  if (engagementType === "delete" || engagementType === "hide") {
    const { error: inboundDeleteErr } = await admin
      .from("tiktok_manage_comments_inbound_comments")
      .delete()
      .eq("organization_id", organizationId)
      .eq("open_id", openId)
      .eq("video_id", trimmedVideoId)
      .eq("comment_id", trimmedCommentId);
    if (inboundDeleteErr) throw new Error(inboundDeleteErr.message);
  }

  const { error: engageErr } = await admin
    .from("tiktok_manage_comments_comment_engagements")
    .upsert({
      organization_id: organizationId,
      open_id: openId,
      video_id: trimmedVideoId,
      comment_id: trimmedCommentId,
      engagement_type: engagementType,
      engaged_by: engagedBy,
      engaged_at: now,
    }, { onConflict: "organization_id,open_id,video_id,comment_id" });

  if (engageErr) throw new Error(engageErr.message);

  const { data: postRow } = await admin
    .from("tiktok_manage_comments_post_inbox_state")
    .select("last_known_comment_count")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .eq("video_id", trimmedVideoId)
    .maybeSingle();

  await reconcilePostHighlight(
    admin,
    organizationId,
    openId,
    trimmedVideoId,
    Number(postRow?.last_known_comment_count ?? 0),
  );

  return getManageCommentsInboxState(admin, organizationId, openId);
}
